// Extraction des informations d'une demande de devis.
// Accepte un formulaire (champs nommés) ou un email brut (champ "text").
// Règle : une information absente reste vide et part dans "aClarifier" — rien n'est inventé.
const resultats = [];
for (const item of $input.all()) {
  const corps = item.json.body ?? item.json;
  const texte = String(corps.text ?? corps.message ?? '');

  const chercher = (regex) => {
    const m = texte.match(regex);
    return m ? m[1].trim() : '';
  };

  const nom = String(corps.nom ?? corps.name ?? '').trim() || chercher(/(?:je m'appelle|nom\s*:)\s*([^\n,.]+)/i);
  const email = String(corps.email ?? corps.from ?? '').trim() || chercher(/([\w.+-]+@[\w-]+\.[\w.]+)/);
  const besoin = String(corps.besoin ?? '').trim() || texte.split('\n').find((l) => l.trim()) || '';
  const budget = String(corps.budget ?? '').trim() || chercher(/(\d[\d\s.,]*\s?(?:€|euros?|k€))/i);
  const delai = String(corps.delai ?? '').trim() || chercher(/d[ée]lai\s*:?\s*([^\n,.]{2,40})/i) || chercher(/((?:avant|d'ici|sous|pour)\s+(?:le\s+)?[^\n,.]{3,40})/i);

  const champs = { nom, email, besoin, budget, delai };
  const aClarifier = Object.entries(champs).filter(([, v]) => !v).map(([k]) => k);

  resultats.push({
    json: {
      ...champs,
      aClarifier: aClarifier.join(', '),
      complet: aClarifier.length === 0,
      recuLe: new Date().toISOString(),
      statut: 'À qualifier',
    },
  });
}
return resultats;

